1	// src/lib/plattform/backend/demo/entwicklung.js
2	//
3	// Projektentwicklung im Demo-Backend – Referenz für plattform/api/entwicklung.py (Vertrag: docs/API.md, Abschnitt 11).
4	// Internes Entwicklungsmanagement: Entwicklungsprojekt mit Projektflächen, Meilenstein-Plan nach Vorlage (Land × Typ)
5	// mit Soll/Ist, Abhängigkeiten, Dokumentenpflicht und Gutachter-Zuweisung, Risikoregister, Behörden-/Stakeholder-Kontakte
6	// (CRM), Entscheidungsprotokoll, Budget/Ist, Pipeline-Wert, Übergabe an Börse bzw. Bau/Betrieb.
7	//
8	// Daten unter db.entwicklung (eigene Sammlung, beim ersten Zugriff einmalig mit Demo-Daten ergänzt – entwicklung-seed.js).
9	//
10	// Rechte (jede Operation prüft Rolle UND Eigentum selbst):
11	//   Backoffice      – Rolle admin mit Bereich „entwicklung“ (rechte.js): lesen ≥ 1 sieht alles, schreiben = 2 pflegt
12	//                     (Unterrollen leitung, projektleitung; akquise/transaktion/buchhaltung/lesen nur lesen)
13	//   Eigentümer      – Konto (oder Team) einer verknüpften Plattform-Fläche: nur vereinfachter Fortschritt (Meilensteine mit
14	//                     externem Titel, Quartal statt Datum), eigene Flächen – keine Risiken, Kosten, Namen, Notizen
15	//   Co-Investor     – Freigabe je Projekt (Konto oder Organisation, Rolle investor): Fortschritt, Termine, freigegebene
16	//                     Risiken (Kennzeichen „extern“) und Dokumente – Freigabe und Zugriff nur mit verifiziertem KYC/KYB
17	//                     (kycRegeln, Schritt „codevelopment“), sonst 409 (Code „kyc“)
18	//   Gutachter       – Rolle gutachter UND Zuweisung am Meilenstein: nur die zugewiesenen Meilensteine, eigene Rückfragen,
19	//                     Upload von Gutachten; kann „in Arbeit“/„eingereicht“ melden, nie erledigen
20	//   sonst           – 403 (Seiten: 404)
21	
22	import { PlattformFehler, konflikt, nichtGefunden, ungueltig, verboten } from "../../fehler";
23	import * as v from "../../validierung";
24	import { darfLesen, darfSchreiben } from "../../rechte";
25	import { LAENDER, BUNDESLAENDER, UPLOAD } from "../../konstanten";
26	import {
27	  BUDGET_KATEGORIEN, ENTSCHEIDUNG_ARTEN, GUTACHTER_FACHGEBIETE, GUTACHTER_QUALIFIKATION, ENTWICKLUNG_OFFEN, ENTWICKLUNG_STATUS, ENTWICKLUNG_TYPEN, KATEGORIEN, KONTAKT_ROLLEN_ENTWICKLUNG,
28	  MEILENSTEIN_FERTIG, MEILENSTEIN_STATUS, PACHT_GESICHERT, PACHT_STATUS, RISIKO_KATEGORIEN, RISIKO_STATUS, VERMARKTUNG, ZIEL_MWP_JAHR,
29	  erzeugtKreis, heuteIso, istUeberfaellig, kritischerPfad, mwpAusFlaeche, offeneVorgaenger, phaseAusMeilensteinen, phaseLabel, pipelineWert,
30	  planBerechnen, planMonate, plusMonate, quartal, risikoAmpel, risikoScore, tageZwischen, verzugTage, vermarktungLabel, vorlage,
31	} from "../../entwicklung";
32	import { PHASEN } from "@/lib/invest/markt";
33	import { intern } from "../demo";
34	import { aendern, lesen, uploadLesen, uploadSchreiben } from "./speicher";
35	import { jetzt, neueId, sha256, slugify, zufallsToken } from "./hilfen";
36	import { teamRolle, darfTeamLesenObjekt } from "./teams";
37	import { entwicklungSeed } from "./entwicklung-seed";
38	import * as anlagenDemo from "./anlagen";
39	
40	import { internSicherheit } from "./sicherheitWerkzeuge";
41	import { kycFreigabeDb, kycSperre } from "./kycRegeln"; // KYC/KYB: Co-Development nur mit verifiziertem Investor
42	
43	const { benachrichtigen, protokoll, nutzerById, nameVon } = intern;
44	const postausgangAnlegen = (...a) => internSicherheit.postausgangAnlegen(...a);
45	
46	const istAdmin = (n) => !!n?.rollen?.includes("admin");
47	const boLesen = (n) => istAdmin(n) && darfLesen(n, "entwicklung");
48	const boSchreiben = (n) => istAdmin(n) && darfSchreiben(n, "entwicklung");
49	const EINLADUNG_TAGE = 14;
50	
51	function angemeldet(n) {
52	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
53	}
54	function leseNoetig(n) {
55	  angemeldet(n);
56	  if (!boLesen(n)) throw verboten("Nur für das Backoffice (Projektentwicklung).");
57	}
58	function schreibNoetig(n) {
59	  angemeldet(n);
60	  if (!boSchreiben(n)) throw verboten(istAdmin(n) ? "Ihre Backoffice-Rolle erlaubt im Bereich „Projektentwicklung“ kein Schreiben." : "Nur für das Backoffice (Projektentwicklung).");
61	}
62	
63	// ================================================================ Datenbestand
64	
65	function leer() {
66	  return { v: 1, projekte: [], flaechen: [], meilensteine: [], risiken: [], entscheidungen: [], budget: [], dokumente: [], rueckfragen: [], einladungen: [], gutachterProfile: [], fristenGeprueftAm: null };
67	}
68	
69	async function lesenBereit() {
70	  const db = await lesen();
71	  if (db.entwicklung?.v) return db;
72	  await aendern(async (d) => {
73	    if (d.entwicklung?.v) return;
74	    d.entwicklung = leer();
75	    try {
76	      await entwicklungSeed(d);
77	    } catch (e) {
78	      console.warn("[plattform-demo] Entwicklungs-Demodaten nicht ergänzt:", e?.message);
79	    }
80	  });
81	  return lesen();
82	}
83	
84	async function aendernBereit(fn) {
85	  await lesenBereit();
86	  return aendern(fn);
87	}
88	
89	const E = (db) => db.entwicklung;
90	const ms = (db, pid) => E(db).meilensteine.filter((m) => m.projektId === pid).sort((a, b) => (a.reihenfolge ?? 0) - (b.reihenfolge ?? 0));
91	const plattformFlaeche = (db, id) => (id ? db.flaechen.find((f) => f.id === id) || null : null);
92	
93	// ================================================================ Gutachter-Profil (Fachgebiete, Qualifikation)
94	
95	function profilDaten(d = {}) {
96	  return {
97	    fachgebiete: v.mehrfach(Array.isArray(d.fachgebiete) ? d.fachgebiete : [], GUTACHTER_FACHGEBIETE),
98	    qualifikation: v.auswahl(d.qualifikation, GUTACHTER_QUALIFIKATION, ""),
99	    buero: v.text(d.buero, 160),
100	    nachweis: v.text(d.nachweis, 300),
101	  };
102	}
103	
104	function profilVon(db, nutzerId) {
105	  return (E(db).gutachterProfile || []).find((x) => x.nutzerId === nutzerId) || null;
106	}
107	
108	function profilAusgabe(db, nutzerId) {
109	  const x = profilVon(db, nutzerId);
110	  return {
111	    nutzerId, ...(personKurz(db, nutzerId) || {}),
112	    fachgebiete: x?.fachgebiete || [], fachgebieteLabel: (x?.fachgebiete || []).map((f) => GUTACHTER_FACHGEBIETE[f] || f),
113	    qualifikation: x?.qualifikation || "", qualifikationLabel: GUTACHTER_QUALIFIKATION[x?.qualifikation] || "", buero: x?.buero || "", nachweis: x?.nachweis || "",
114	  };
115	}
116	
117	function profilSetzen(db, nutzerId, d) {
118	  E(db).gutachterProfile ||= [];
119	  const neu = profilDaten(d);
120	  const alt = profilVon(db, nutzerId);
121	  if (alt) Object.assign(alt, Object.fromEntries(Object.entries(neu).filter(([k, w]) => Object.hasOwn(d, k) || (Array.isArray(w) ? w.length : w))), { geaendertAm: jetzt() });
122	  else E(db).gutachterProfile.push({ nutzerId, ...neu, geaendertAm: jetzt() });
123	}
124	
125	// ================================================================ Zugriff
126	
127	/** Eigentümer (bzw. Team) einer verknüpften Plattform-Fläche? */
128	function istEigentuemer(db, n, p) {
129	  return E(db).flaechen.some((pf) => {
130	    if (pf.projektId !== p.id || !pf.flaecheId) return false;
131	    const f = plattformFlaeche(db, pf.flaecheId);
132	    return !!f && (f.nutzerId === n.id || darfTeamLesenObjekt(db, n, f));
133	  });
134	}
135	
136	/** Co-Development-Freigabe des Kontos bzw. seiner Organisation (ohne KYC-Prüfung) */
137	function freigabeRoh(db, n, p) {
138	  if (!n?.rollen?.includes("investor")) return null;
139	  return (p.freigaben || []).find((fg) => (fg.nutzerId && fg.nutzerId === n.id) || (fg.organisationId && teamRolle(db, n.id, fg.organisationId))) || null;
140	}
141	
142	/** KYC-Ziel des zugreifenden Investors: eigener Fall bzw. KYB der freigegebenen (oder aktiven) Organisation */
143	const kycZiel = (n, fg) => ({ kontoId: n.id, organisationId: fg?.organisationId || n.organisation?.id || null });
144	
145	/** Wirksame Freigabe: nur mit verifiziertem KYC/KYB (Schritt „codevelopment“) */
146	function freigabeFuer(db, n, p) {
147	  const fg = freigabeRoh(db, n, p);
148	  return fg && kycFreigabeDb(db, "codevelopment", kycZiel(n, fg)).ok ? fg : null;
149	}
150	
151	function gutachterMeilensteine(db, n, p) {
152	  if (!n?.rollen?.includes("gutachter")) return [];
153	  return ms(db, p.id).filter((m) => (m.gutachterIds || []).includes(n.id));
154	}
155	
156	/** Zugriffe des Nutzers auf ein Projekt: { backoffice, eigentuemer, investor (Freigabe|null), gutachter [Meilensteine] } */
157	function zugriffe(db, n, p) {
158	  if (!n || !p) return null;
159	  const fg = freigabeRoh(db, n, p);
160	  const kyc = fg ? kycFreigabeDb(db, "codevelopment", kycZiel(n, fg)) : null;
161	  const z = { backoffice: boLesen(n), eigentuemer: istEigentuemer(db, n, p), investor: kyc?.ok ? fg : null, investorKyc: kyc && !kyc.ok ? kyc : null, gutachter: gutachterMeilensteine(db, n, p) };
162	  z.irgendeiner = z.backoffice || z.eigentuemer || !!z.investor || z.gutachter.length > 0;
163	  return z;
164	}
165	
166	function projektLaden(db, id) {
167	  const p = E(db).projekte.find((x) => x.id === v.kennung(id));
168	  if (!p) throw nichtGefunden("Entwicklungsprojekt nicht gefunden.");
169	  return p;
170	}
171	
172	function projektIntern(db, n, id) {
173	  leseNoetig(n);
174	  return projektLaden(db, id);
175	}
176	
177	// ================================================================ Berechnungen
178	
179	/** Plan, kritischer Pfad, Phase, Pipeline, Fortschritt, Verzug eines Projekts */
180	function kennzahlen(db, p, heute = heuteIso()) {
181	  const liste = ms(db, p.id);
182	  const kp = kritischerPfad(liste, { heute });
183	  const phase = phaseAusMeilensteinen(liste);
184	  const flaechen = E(db).flaechen.filter((pf) => pf.projektId === p.id);
185	  const aktiv = liste.filter((m) => m.status !== "entfaellt");
186	  const erledigt = aktiv.filter((m) => m.status === "erledigt").length;
187	  const ueberfaellig = liste.filter((m) => istUeberfaellig(m, heute));
188	  const cod = liste.find((m) => m.phase === "cod");
189	  const prognoseCod = cod ? kp.je.get(cod.id)?.prognoseEnde || cod.sollEnde : kp.projektEnde;
190	  const codVerzugMonate = p.zielCod && prognoseCod ? Math.max(0, Math.round(tageZwischen(p.zielCod.length === 4 ? `${p.zielCod}-12-01` : `${p.zielCod}-01`, prognoseCod) / 30.4)) : 0;
191	  const budget = E(db).budget.filter((b) => b.projektId === p.id);
192	  const risiken = E(db).risiken.filter((r) => r.projektId === p.id && !["geschlossen"].includes(r.status));
193	  const naechste = liste.filter((m) => !MEILENSTEIN_FERTIG.includes(m.status)).sort((a, b) => String(a.sollEnde).localeCompare(String(b.sollEnde)))[0] || null;
194	  return {
195	    phase,
196	    phaseLabel: phaseLabel(phase),
197	    pipeline: pipelineWert({ mwp: p.typ === "speicher" ? p.mwp || (p.mwh || 0) / 2 : p.mwp, phase, wahrscheinlichkeit: p.wahrscheinlichkeit }),
198	    fortschritt: aktiv.length ? Math.round((erledigt / aktiv.length) * 100) : 0,
199	    meilensteine: { gesamt: aktiv.length, erledigt, ueberfaellig: ueberfaellig.length, kritischUeberfaellig: ueberfaellig.filter((m) => kp.je.get(m.id)?.kritisch).length },
200	    prognoseCod,
201	    codVerzugMonate,
202	    flaecheHa: Math.round(flaechen.reduce((s, f) => s + (Number(f.ha) || 0), 0) * 10) / 10,
203	    flaecheGesichertHa: Math.round(flaechen.filter((f) => PACHT_GESICHERT.includes(f.pachtStatus)).reduce((s, f) => s + (Number(f.ha) || 0), 0) * 10) / 10,
204	    budgetPlan: budget.reduce((s, b) => s + (Number(b.planEur) || 0), 0),
205	    budgetIst: budget.reduce((s, b) => s + (Number(b.istEur) || 0), 0),
206	    risikoMax: risiken.reduce((m, r) => Math.max(m, risikoScore(r)), 0),
207	    risikenOffen: risiken.length,
208	    naechsterMeilenstein: naechste ? { id: naechste.id, titel: naechste.titel, sollEnde: naechste.sollEnde } : null,
209	    kp,
210	  };
211	}
212	
213	// ================================================================ Ausgabe (Backoffice)
214	
215	const personKurz = (db, id) => {
216	  const u = id ? nutzerById(db, id) : null;
217	  return u ? { id: u.id, name: nameVon(db, u.id), email: u.email } : null;
218	};
219	
220	function meilensteinAusgabe(db, m, kp, heute) {
221	  const k = kp?.je.get(m.id);
222	  const doks = E(db).dokumente.filter((d) => d.meilensteinId === m.id);
223	  return {
224	    ...m,
225	    statusLabel: MEILENSTEIN_STATUS[m.status]?.label || m.status,
226	    kategorieLabel: KATEGORIEN[m.kategorie]?.label || m.kategorie,
227	    verantwortlich: personKurz(db, m.verantwortlichId),
228	    gutachter: (m.gutachterIds || []).map((g) => personKurz(db, g)).filter(Boolean),
229	    verzugTage: verzugTage(m, heute),
230	    ueberfaellig: istUeberfaellig(m, heute),
231	    kritisch: !!k?.kritisch,
232	    puffer: k?.puffer ?? null,
233	    prognoseStart: k?.prognoseStart || m.sollStart,
234	    prognoseEnde: k?.prognoseEnde || m.sollEnde,
235	    dokumente: doks.length,
236	    pflichtErfuellt: (m.dokumentPflicht || []).map((pf) => ({ name: pf, erfuellt: doks.some((d) => d.pflicht === pf) })),
237	    rueckfragen: E(db).rueckfragen.filter((r) => r.meilensteinId === m.id).length,
238	  };
239	}
240	
241	function projektKurz(db, p, heute = heuteIso()) {
242	  const k = kennzahlen(db, p, heute);
243	  const { kp, ...rest } = k;
244	  return {
245	    id: p.id, titel: p.titel, typ: p.typ, typLabel: ENTWICKLUNG_TYPEN[p.typ] || p.typ, land: p.land, bundesland: p.bundesland, gemeinde: p.gemeinde || "",
246	    mwp: p.mwp, mwh: p.mwh, status: p.status, statusLabel: ENTWICKLUNG_STATUS[p.status]?.label || p.status, zielCod: p.zielCod || "",
