291	export async function entwicklungPortfolio(n, { q = "", status = "" } = {}) {
292	  leseNoetig(n);
293	  await fristenLazy(n);
294	  const db = await lesenBereit();
295	  const heute = heuteIso();
296	  const such = v.text(q, 80).toLowerCase();
297	  const alle = E(db).projekte
298	    .filter((p) => !status || p.status === status)
299	    .filter((p) => !such || [p.titel, p.gemeinde, p.bundesland, p.id].join(" ").toLowerCase().includes(such));
300	  const projekte = alle.map((p) => projektKurz(db, p, heute));
301	  const offen = projekte.filter((p) => ENTWICKLUNG_OFFEN.includes(p.status));
302	
303	  const jePhase = [{ id: null, label: "Akquise" }, ...PHASEN.map((x) => ({ id: x.id, label: x.kurz }))].map((ph) => {
304	    const t = offen.filter((p) => (p.phase || null) === ph.id);
305	    return { phase: ph.id, label: ph.label, anzahl: t.length, mwp: runde(t.reduce((s, p) => s + (p.mwp || 0), 0)), wert: t.reduce((s, p) => s + p.pipeline.wert, 0) };
306	  });
307	  const jeLand = Object.keys(LAENDER).map((l) => {
308	    const t = offen.filter((p) => p.land === l);
309	    return { land: l, label: LAENDER[l], anzahl: t.length, mwp: runde(t.reduce((s, p) => s + (p.mwp || 0), 0)), wert: t.reduce((s, p) => s + p.pipeline.wert, 0) };
310	  });
311	  const jahre = new Map();
312	  for (const p of projekte.filter((x) => x.status !== "abgebrochen")) {
313	    const j = Number(String(p.prognoseCod || p.zielCod || "").slice(0, 4));
314	    if (!j) continue;
315	    const e = jahre.get(j) || { jahr: j, mwp: 0, mwpGewichtet: 0, anzahl: 0 };
316	    e.mwp = runde(e.mwp + (p.mwp || 0));
317	    e.mwpGewichtet = runde(e.mwpGewichtet + p.pipeline.gewichtetMwp);
318	    e.anzahl++;
319	    jahre.set(j, e);
320	  }
321	  const verzug = [];
322	  const fristen = [];
323	  const in30 = plusMonate(heute, 1);
324	  for (const p of E(db).projekte.filter((x) => ENTWICKLUNG_OFFEN.includes(x.status))) {
325	    const kp = kritischerPfad(ms(db, p.id), { heute });
326	    for (const m of ms(db, p.id)) {
327	      if (MEILENSTEIN_FERTIG.includes(m.status)) continue;
328	      const eintrag = { projektId: p.id, projektTitel: p.titel, meilensteinId: m.id, titel: m.titel, sollEnde: m.sollEnde, status: m.status, kritisch: !!kp.je.get(m.id)?.kritisch, verantwortlich: personKurz(db, m.verantwortlichId || p.projektleiterId) };
329	      if (istUeberfaellig(m, heute)) verzug.push({ ...eintrag, tage: verzugTage(m, heute) });
330	      else if (m.sollEnde && m.sollEnde <= in30) fristen.push({ ...eintrag, inTagen: tageZwischen(heute, m.sollEnde) });
331	    }
332	  }
333	  verzug.sort((a, b) => Number(b.kritisch) - Number(a.kritisch) || b.tage - a.tage);
334	  fristen.sort((a, b) => String(a.sollEnde).localeCompare(String(b.sollEnde)));
335	  const leiter = db.nutzer.filter((u) => u.aktiv && u.rollen.includes("admin") && darfSchreiben(u, "entwicklung"));
336	  const auslastung = leiter
337	    .map((u) => {
338	      const eigene = E(db).projekte.filter((p) => p.projektleiterId === u.id && ENTWICKLUNG_OFFEN.includes(p.status));
339	      const offeneMs = E(db).meilensteine.filter((m) => !MEILENSTEIN_FERTIG.includes(m.status) && (m.verantwortlichId === u.id || (!m.verantwortlichId && eigene.some((p) => p.id === m.projektId))));
340	      return {
341	        id: u.id, name: nameVon(db, u.id), projekte: eigene.length, mwp: runde(eigene.reduce((s, p) => s + (p.mwp || 0), 0)),
342	        offeneMeilensteine: offeneMs.length, ueberfaellig: offeneMs.filter((m) => istUeberfaellig(m, heute)).length, faellig30: offeneMs.filter((m) => m.sollEnde && m.sollEnde >= heute && m.sollEnde <= in30).length,
343	      };
344	    })
345	    .filter((a) => a.projekte || a.offeneMeilensteine)
346	    .sort((a, b) => b.offeneMeilensteine - a.offeneMeilensteine);
347	  return {
348	    projekte,
349	    summen: {
350	      anzahl: offen.length,
351	      mwp: runde(offen.reduce((s, p) => s + (p.mwp || 0), 0)),
352	      mwpGewichtet: runde(offen.reduce((s, p) => s + p.pipeline.gewichtetMwp, 0)),
353	      volumen: offen.reduce((s, p) => s + p.pipeline.volumen, 0),
354	      wert: offen.reduce((s, p) => s + p.pipeline.wert, 0),
355	      jePhase, jeLand, jeJahr: [...jahre.values()].sort((a, b) => a.jahr - b.jahr), zielMwpJahr: ZIEL_MWP_JAHR,
356	    },
357	    verzug, fristen, auslastung,
358	    darfBearbeiten: boSchreiben(n),
359	  };
360	}
