386	function stammdaten(d, alt = {}) {
387	  const has = (k) => Object.hasOwn(d, k);
388	  const f = {};
389	  if (has("titel") || !alt.id) f.titel = v.text(d.titel, 120);
390	  if (has("typ") || !alt.id) f.typ = v.auswahl(d.typ, ENTWICKLUNG_TYPEN, alt.typ || "freiflaeche");
391	  if (has("land") || !alt.id) f.land = v.auswahl(d.land, LAENDER, alt.land || "DE");
392	  const land = f.land || alt.land;
393	  if (has("bundesland") || !alt.id) f.bundesland = v.auswahl(d.bundesland, BUNDESLAENDER[land] || [], "");
394	  for (const k of ["gemeinde", "landkreis", "nvp", "netzbetreiber"]) if (has(k)) f[k] = v.text(d[k], 160);
395	  if (has("mwp")) f.mwp = v.zahl(d.mwp, { min: 0, max: 5000, stellen: 2 }) ?? 0;
396	  if (has("mwh")) f.mwh = v.zahl(d.mwh, { min: 0, max: 20000, stellen: 1 }) ?? 0;
397	  if (has("zielCod")) f.zielCod = v.monat(d.zielCod) || "";
398	  if (has("vermarktung") || !alt.id) f.vermarktung = v.auswahl(d.vermarktung, VERMARKTUNG, alt.vermarktung || "eeg");
399	  if (has("status")) f.status = v.auswahl(d.status, ENTWICKLUNG_STATUS, alt.status || "aktiv");
400	  if (has("beschreibung")) f.beschreibung = v.mehrzeilig(d.beschreibung, 4000);
401	  if (has("wahrscheinlichkeit")) f.wahrscheinlichkeit = d.wahrscheinlichkeit === null || d.wahrscheinlichkeit === "" ? null : v.zahl(d.wahrscheinlichkeit, { min: 0, max: 1, stellen: 2 });
402	  if (has("start")) f.start = /^20\d\d-\d\d-\d\d$/.test(String(d.start || "")) ? d.start : alt.start || heuteIso();
403	  const neu = { ...alt, ...f };
404	  v.pflicht(neu.titel?.length >= 3, "Bitte geben Sie einen Projekttitel an (mind. 3 Zeichen).");
405	  v.pflicht(!!neu.bundesland, "Bitte wählen Sie Bundesland bzw. Kanton.");
406	  if (neu.typ === "speicher") v.pflicht((neu.mwh || 0) > 0 || (neu.mwp || 0) > 0, "Bitte geben Sie Leistung (MW) oder Kapazität (MWh) des Speichers an.");
407	  else v.pflicht((neu.mwp || 0) > 0, "Bitte geben Sie die geplante Leistung in MWp an.");
408	  return neu;
409	}
