753	export async function entwicklungEintragSpeichern(n, projektId, { art, id = null, daten = {} } = {}) {
754	  schreibNoetig(n);
755	  if (!EINTRAG[art]) throw ungueltig("Unbekannte Eintragsart.");
756	  return aendernBereit((db) => {
757	    const p = projektLaden(db, projektId);
758	    const e = EINTRAG[art](db, n, p, id ? v.kennung(id) : null, daten || {});
759	    p.geaendertAm = jetzt();
760	    return { eintrag: e, projekt: projektAusgabe(db, n, p) };
761	  });
762	}
