767	    const p = projektLaden(db, projektId);
768	    const k = v.kennung(id);
769	    const weg = (liste, pred) => {
770	      const i = liste.findIndex(pred);
771	      if (i < 0) throw nichtGefunden("Eintrag nicht gefunden.");
772	      return liste.splice(i, 1)[0];
773	    };
774	    if (art === "flaeche") weg(E(db).flaechen, (x) => x.id === k && x.projektId === p.id);
775	    else if (art === "risiko") weg(E(db).risiken, (x) => x.id === k && x.projektId === p.id);
776	    else if (art === "budget") {
777	      const b = E(db).budget.find((x) => x.id === k && x.projektId === p.id);
778	      if (b?.istQuelle === "erpnext") throw konflikt("Positionen mit Ist-Werten aus ERPNext werden dort gepflegt.");
