		"vonId": d.von_id, "von": name_von(d.von_id), "am": iso(d.am), "freigabeInvestor": bool(cint(d.freigabe_investor)), "fuerGutachter": bool(cint(d.fuer_gutachter)),
		"link": f"/api/portal/entwicklung/dokumente/{d.name}",
