// src/lib/plattform/server/route.js
//
// Gemeinsamer Rahmen aller Plattform-APIs:
//  - CSRF-Schutz: Mutationen nur mit passendem Origin-Header UND Content-Type JSON
//    (Uploads: multipart + Kopfzeile X-Plattform-Upload). Ein fremdes Formular kann weder
//    JSON senden noch eigene Kopfzeilen setzen; fremde fetch-Aufrufe scheitern am Origin.
//  - Sitzung aus dem signierten Cookie, Nutzer frisch aus dem Backend (Rollen, Sperre, Version)
//  - Rollenprüfung vorab (Eigentum prüft das Backend)
//  - Rate-Limits, Größenbegrenzung des Bodys
//  - Fehler → { ok:false, error, code } mit passendem HTTP-Status, Interna nur ins Log

import { NextResponse } from "next/server";
import { backend } from "../backend";
import { PlattformFehler } from "../fehler";
import { cookieName, cookieOptionen, tokenErstellen, tokenPruefen } from "../sitzung";
import { ipAdresse } from "@/lib/ipAdresse";
import { SITE } from "@/data/site";
import { grenze, rateLimit } from "./rateLimit";
import { adminRechtPruefen } from "./rechte"; // Backoffice-Unterrollen (Rechte-Matrix)

const KEIN_CACHE = { "Cache-Control": "no-store" };

export function antwort(daten, status = 200) {
  return NextResponse.json(daten, { status, headers: KEIN_CACHE });
}

export function fehlerAntwort(e) {
  if (e instanceof PlattformFehler) {
    return antwort({ ok: false, error: e.message, code: e.code }, e.status);
  }
  console.error("[plattform] Unerwarteter Fehler:", e);
  return antwort({ ok: false, error: "Es ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.", code: "fehler" }, 500);
}

function hostVon(url) {
  try {
    return new URL(url).host.toLowerCase();
  } catch {
    return "";
  }

export const darfSchreiben = (n, bereich) => stufe(n, bereich) >= 2;

/** Bereich je Objektart (Statuswechsel, Zuweisung, Aufgaben am Objekt, Export) */
export const BEREICH_FUER_ART = {
  vorgang: "vorgaenge",
  flaeche: "flaechen",
  projekt: "projekte",
  interesse: "interessen",
  provision: "provisionen",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  projekte: "projekte",
  interessen: "interessen",
  provisionen: "provisionen",
};

/** Bereich einer Admin-API aus dem Pfad (/api/admin/<teil>/…) */
const API_BEREICH = {
  uebersicht: "cockpit",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  projekte: "projekte",
  interessen: "interessen",
  provisionen: "provisionen",
  aufgaben: "aufgaben",
  nutzer: "nutzer",
  "demo-links": "nutzer",
  aktivitaeten: "protokoll",
  protokoll: "protokoll",
  postausgang: "postausgang",
  crm: "crm",
  akquise: "akquise",
  gebiete: "akquise",
  automationen: "automationen",
  vorlagen: "vorlagen",
  berichte: "berichte",
  rechte: "rechte",
  dealroom: "interessen", // Deal-Room (Q&A, Datenraum) – Transaktion
  bieter: "interessen", // Bieterverfahren – Transaktion
  anlagen: "anlagen", // Anlagen & Monitoring
  compliance: "compliance", // KYC/KYB
  entwicklung: "entwicklung", // Projektentwicklung
  finanzen: "finanzen", // ERPNext-Finanzen & Abrechnung
  finanzierung: "finanzierung", // Bankfinanzierung Eigenbetrieb
  signatur: "signatur", termine: "kalender", support: "support", hr: "team", wissen: "wissen", // Signatur, Termine, Service & HR
  gesellschaften: "gesellschaften", bonitaet: "bonitaet", register: "register", // Dienste: Firmen, Bonität, Identität
  geodaten: "geodaten", // Geodaten & Akquise-Engine
  energie: "energie", // Energiebeschaffung & Versorger-Ausschreibung
  grundbuch: "grundbuch", closing: "closing", // Grundbuch & Closing
};

/**
 * Welche Rechte braucht eine Admin-API? Liefert [{ bereich, stufe }] (alle müssen erfüllt sein).
 * `body` wird für Status/Zuweisung (Objektart) und Aufgaben mit Bezug ausgewertet.
 */
export function apiAnforderungen({ pfad, methode = "GET", body, params = {}, recht } = {}) {
  const schreiben = !["GET", "HEAD", "OPTIONS"].includes(String(methode).toUpperCase());
  const teile = String(pfad || "").split("?")[0].split("/").filter(Boolean); // ["api","admin",teil,…]
  const teil = teile[2] || "";
  const st = schreiben ? 2 : 1;
  if (recht) return [].concat(recht).map((r) => (typeof r === "string" ? { bereich: r, stufe: st } : r));
  if (teil === "status" || teil === "zuweisen") {
    return [{ bereich: BEREICH_FUER_ART[body?.art] || "sonstiges", stufe: 2 }];
  }
  if (teil === "export") {
    const art = params?.art || teile[3];
    return [{ bereich: "export", stufe: 1 }, { bereich: BEREICH_FUER_ART[art] || "sonstiges", stufe: 1 }];
  }
  if (teil === "berichte") return [{ bereich: "berichte", stufe: 1 }]; // PDF/CSV-Abruf ist Lesen
  const anf = [{ bereich: API_BEREICH[teil] || "sonstiges", stufe: st }];
  if (teil === "aufgaben" && schreiben && body?.bezugArt && BEREICH_FUER_ART[body.bezugArt]) {
    anf.push({ bereich: BEREICH_FUER_ART[body.bezugArt], stufe: 1 });
  }
  if (teil === "automationen" && teile[3] === "testlauf") anf[0].stufe = 1; // Testlauf ändert nichts
  if (teil === "vorlagen" && teile[3] === "vorschau") anf[0].stufe = 1;
  return anf;
}

/** Fehlende Rechte (leer = erlaubt) */
export function fehlendeRechte(n, anforderungen) {
  return anforderungen.filter((a) => stufe(n, a.bereich) < a.stufe);
}

/** Bereich einer Admin-Seite (/portal/admin/<teil>) */
const SEITEN_BEREICH = {
  "": "cockpit",
  aufgaben: "aufgaben",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  akquise: "akquise",
  projekte: "projekte",
  interessen: "interessen",
  dealroom: "interessen", // Deal-Room-Übersicht (Gebote, Q&A, Zugriffe) – wie die API /api/admin/dealroom
  deals: "provisionen",
  nutzer: "nutzer",
  postausgang: "postausgang",
  crm: "crm",
  automationen: "automationen",
  vorlagen: "vorlagen",
  berichte: "berichte",
  protokoll: "protokoll",
  rechte: "rechte",
  anlagen: "anlagen", // Anlagen & Monitoring
  compliance: "compliance", // KYC/KYB
  entwicklung: "entwicklung", // Projektentwicklung
  finanzen: "finanzen", // ERPNext-Finanzen & Abrechnung
  finanzierung: "finanzierung", // Bankfinanzierung Eigenbetrieb
  kalender: "kalender", support: "support", team: "team", wissen: "wissen", // Termine, Service & HR
  gesellschaften: "gesellschaften", bonitaet: "bonitaet", // Dienste: Firmen, Bonität, Identität
  energie: "energie", // Energiebeschaffung
  grundbuch: "grundbuch", closing: "closing", // Grundbuch & Closing
};

export function seitenBereich(pfad) {
  const teile = String(pfad || "").split("?")[0].split("/").filter(Boolean); // ["portal","admin",teil]
  if (teile[0] !== "portal" || teile[1] !== "admin") return null;
  if (teile[2] === "akquise" && ["karte", "kampagnen", "gemeinden", "sperrliste"].includes(teile[3])) return "geodaten"; // Geodaten & Akquise-Karte, Kampagnen, Gemeinde-Screening (A1b)
  return SEITEN_BEREICH[teile[2] || ""] || "sonstiges";
}

export const STUFE_LABEL = ["–", "lesen", "schreiben"];

// POST   /api/admin/entwicklung/[id]/eintraege – { art: flaeche|meilenstein|risiko|entscheidung|budget|kontakt|freigabe, id?, daten }
//        Meilenstein: Abhängigkeiten ohne Kreis (409), „erledigt“ erst nach allen Vorgängern (409) und mit Dokumentenpflicht
//        oder begründetem Verzicht (422); Entscheidungen sind unveränderlich (409)
// DELETE /api/admin/entwicklung/[id]/eintraege?art=…&id=…
import { route } from "@/lib/plattform/server/route";
import { entwicklungBackend } from "@/lib/plattform/backend/entwicklung";

export const POST = route({ admin: true }, async ({ nutzer, params, body }) => ({
  ok: true,
  ...(await entwicklungBackend().entwicklungEintragSpeichern(nutzer, params.id, { art: String(body.art || ""), id: body.id || null, daten: body.daten && typeof body.daten === "object" ? body.daten : {} })),
}));

export const DELETE = route({ admin: true, json: false }, async ({ nutzer, params, suche }) => ({
  ok: true,
  projekt: await entwicklungBackend().entwicklungEintragLoeschen(nutzer, params.id, { art: suche.get("art") || "", id: suche.get("id") || "" }),
}));
// POST /api/admin/entwicklung/fristen – Fristen-Erinnerungen jetzt ausführen (≤ 7 Tage bzw. überfällig, je Stufe einmal).
//      Im Betrieb täglich per Frappe-Scheduler (oekoinvest_app.plattform.api.entwicklung.fristen_taeglich).
import { route } from "@/lib/plattform/server/route";
import { entwicklungBackend } from "@/lib/plattform/backend/entwicklung";

export const POST = route({ admin: true }, async ({ nutzer }) => ({ ok: true, ...(await entwicklungBackend().entwicklungFristen(nutzer)) }));

