r = await pl.post(`/api/admin/entwicklung/${sid}/eintraege`, { art: "flaeche", daten: { bezeichnung: `Steuerfläche ${LAUF}`, eigentuemerName: "Test", ha: 9, pachtStatus: "verhandlung" } });
const sfid = r.json.eintrag?.id;
